import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync, readdirSync} from 'node:fs';
import {createServer} from 'node:http';
import {once} from 'node:events';
import {ApiClient, ApiError} from '../src/api/client.ts';

for (const file of readdirSync('tests/recordings').filter(name => name.endsWith('.har'))) {
    const recording = JSON.parse(readFileSync('tests/recordings/' + file, 'utf8'));
    for (const entry of recording.log.entries) {
        test(file + ' ' + entry.request.url, async () => {
            let observed;
            const server = createServer((request, response) => {
                observed = {url: request.url, method: request.method};
                response.writeHead(entry.response.status, {'Content-Type': 'application/json', ...Object.fromEntries(entry.response.headers.map(h => [h.name, h.value]))});
                response.end(entry.response.content.text);
            });
            server.listen(0, '127.0.0.1');
            await once(server, 'listening');
            try {
                const client = new ApiClient('http://127.0.0.1:' + server.address().port);
                const url = new URL(entry.request.url);
                const pending = client.request(url.pathname, Object.fromEntries(url.searchParams));
                if (entry.response.status >= 400) {
                    await assert.rejects(pending, error => error instanceof ApiError && error.status === entry.response.status && error.code === JSON.parse(entry.response.content.text).error.code);
                } else {
                    const result = await pending;
                    assert.deepEqual(result, JSON.parse(entry.response.content.text).data);
                }
                assert.deepEqual(observed, {url: new URL(entry.request.url).pathname + new URL(entry.request.url).search, method: entry.request.method});
            } finally {
                server.closeAllConnections();
                await new Promise(resolve => server.close(resolve));
            }
        });
    }
}
